const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const path = require("path");

// Icon rendering
function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}
async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Color palette - Midnight/Deep Tech theme
const C = {
  bg_dark: "0F1629",
  bg_mid: "1A2342",
  bg_card: "212B4A",
  bg_light: "F4F6FB",
  accent: "00D4AA",    // teal-green
  accent2: "3B82F6",   // blue
  accent3: "F59E0B",   // amber
  white: "FFFFFF",
  text_light: "CBD5E1",
  text_muted: "8892A8",
  text_dark: "1E293B",
  card_border: "2D3A5C",
};

const FONT_H = "Trebuchet MS";
const FONT_B = "Calibri";

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.25 });

async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "DeepSeek Research";
  pres.title = "DeepSeek-V2: Efficient MoE Language Model with Multi-Head Latent Attention";

  const { FaBolt, FaMemory, FaRocket, FaBrain, FaCogs, FaChartBar, FaComments, FaLightbulb, FaCheckCircle, FaArrowDown, FaArrowUp, FaTachometerAlt } = require("react-icons/fa");

  // Helper: add a dark slide with optional top accent line
  function darkSlide() {
    const s = pres.addSlide();
    s.background = { color: C.bg_dark };
    return s;
  }

  // Helper: slide title bar
  function addSlideTitle(slide, title, subtitle) {
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });
    slide.addText(title, {
      x: 0.6, y: 0.3, w: 8.8, h: 0.55,
      fontFace: FONT_H, fontSize: 24, bold: true, color: C.white, margin: 0,
    });
    if (subtitle) {
      slide.addText(subtitle, {
        x: 0.6, y: 0.85, w: 8.8, h: 0.35,
        fontFace: FONT_B, fontSize: 12, color: C.text_muted, margin: 0,
      });
    }
  }

  // Helper: card background
  function addCard(slide, x, y, w, h) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w, h,
      fill: { color: C.bg_card },
      shadow: makeShadow(),
      line: { color: C.card_border, width: 0.5 },
    });
  }

  // ===================== SLIDE 1: TITLE =====================
  {
    const s = darkSlide();
    // Full-bleed dark bg with accent strip at bottom
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 4.8, w: 10, h: 0.825, fill: { color: C.accent } });
    s.addText("DeepSeek-V2", {
      x: 0.8, y: 0.9, w: 8.4, h: 1.2,
      fontFace: FONT_H, fontSize: 48, bold: true, color: C.white, margin: 0,
    });
    s.addText("A Strong, Economical, and Efficient\nMixture-of-Experts Language Model", {
      x: 0.8, y: 2.1, w: 8.4, h: 0.9,
      fontFace: FONT_B, fontSize: 20, color: C.text_light, margin: 0,
    });
    // Key stats row
    const stats = [
      { val: "236B", label: "Total Parameters" },
      { val: "21B", label: "Activated / Token" },
      { val: "128K", label: "Context Length" },
      { val: "8.1T", label: "Training Tokens" },
    ];
    stats.forEach((st, i) => {
      const sx = 0.8 + i * 2.25;
      addCard(s, sx, 3.2, 2.0, 1.35);
      s.addText(st.val, {
        x: sx, y: 3.3, w: 2.0, h: 0.6,
        fontFace: FONT_H, fontSize: 28, bold: true, color: C.accent, align: "center", margin: 0,
      });
      s.addText(st.label, {
        x: sx, y: 3.9, w: 2.0, h: 0.45,
        fontFace: FONT_B, fontSize: 11, color: C.text_muted, align: "center", margin: 0,
      });
    });
    s.addText("Multi-Head Latent Attention  ·  DeepSeekMoE", {
      x: 0.8, y: 4.85, w: 8.4, h: 0.7,
      fontFace: FONT_H, fontSize: 16, bold: true, color: C.bg_dark, align: "center", margin: 0,
    });
  }

  // ===================== SLIDE 2: MOTIVATION =====================
  {
    const s = darkSlide();
    addSlideTitle(s, "The LLM Scaling Dilemma", "Performance vs. Training Cost and Inference Speed");

    // Left column - problem framing
    addCard(s, 0.6, 1.4, 4.2, 3.8);
    const problemIcon = await iconToBase64Png(FaBolt, "#F59E0B", 256);
    s.addImage({ data: problemIcon, x: 0.9, y: 1.6, w: 0.4, h: 0.4 });
    s.addText("The Problem", {
      x: 1.4, y: 1.6, w: 3.0, h: 0.4,
      fontFace: FONT_H, fontSize: 16, bold: true, color: C.accent3, margin: 0,
    });
    s.addText([
      { text: "Scaling dense models improves quality but:", options: { breakLine: true, color: C.text_light, fontSize: 13 } },
      { text: "", options: { breakLine: true, fontSize: 8 } },
      { text: "Training costs grow super-linearly with parameter count", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 12 } },
      { text: "KV cache size scales with model dimension × layers, bottlenecking inference", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 12 } },
      { text: "Generation throughput drops as models grow larger", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 12 } },
      { text: "Existing fixes (GQA/MQA) trade performance for speed", options: { bullet: true, color: C.text_light, fontSize: 12 } },
    ], { x: 0.9, y: 2.2, w: 3.7, h: 2.8, fontFace: FONT_B, margin: 0, valign: "top" });

    // Right column - solution
    addCard(s, 5.2, 1.4, 4.2, 3.8);
    const solIcon = await iconToBase64Png(FaRocket, "#00D4AA", 256);
    s.addImage({ data: solIcon, x: 5.5, y: 1.6, w: 0.4, h: 0.4 });
    s.addText("DeepSeek-V2's Answer", {
      x: 6.0, y: 1.6, w: 3.0, h: 0.4,
      fontFace: FONT_H, fontSize: 16, bold: true, color: C.accent, margin: 0,
    });
    s.addText([
      { text: "Two architectural innovations:", options: { breakLine: true, color: C.text_light, fontSize: 13 } },
      { text: "", options: { breakLine: true, fontSize: 8 } },
      { text: "Multi-Head Latent Attention (MLA)", options: { bullet: true, breakLine: true, color: C.accent, fontSize: 12, bold: true } },
      { text: "Compresses KV cache by 93.3% while outperforming standard MHA", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 11, indentLevel: 1 } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "DeepSeekMoE", options: { bullet: true, breakLine: true, color: C.accent, fontSize: 12, bold: true } },
      { text: "Activates only 21B of 236B params, cutting training cost by 42.5%", options: { bullet: true, color: C.text_light, fontSize: 11, indentLevel: 1 } },
    ], { x: 5.5, y: 2.2, w: 3.7, h: 2.8, fontFace: FONT_B, margin: 0, valign: "top" });
  }

  // ===================== SLIDE 3: ARCHITECTURE OVERVIEW =====================
  {
    const s = darkSlide();
    addSlideTitle(s, "DeepSeek-V2 Architecture", "MLA + DeepSeekMoE in a Transformer Block");
    // Center the architecture diagram
    s.addImage({
      path: path.resolve("/app/benchmark/assets/figure_1.jpg"),
      x: 1.2, y: 1.3, w: 7.6, h: 4.0,
      sizing: { type: "contain", w: 7.6, h: 4.0 },
    });
    // Caption
    s.addText("Figure 1: Each Transformer block replaces standard MHA with MLA and dense FFN with DeepSeekMoE", {
      x: 0.6, y: 5.1, w: 8.8, h: 0.35,
      fontFace: FONT_B, fontSize: 10, italic: true, color: C.text_muted, align: "center", margin: 0,
    });
  }

  // ===================== SLIDE 4: MLA MECHANISM =====================
  {
    const s = darkSlide();
    addSlideTitle(s, "Multi-Head Latent Attention (MLA)", "Low-rank KV joint compression with decoupled RoPE");

    // Left: key points
    addCard(s, 0.6, 1.4, 4.0, 3.8);
    s.addText("How MLA Works", {
      x: 0.9, y: 1.55, w: 3.5, h: 0.35,
      fontFace: FONT_H, fontSize: 15, bold: true, color: C.accent, margin: 0,
    });
    s.addText([
      { text: "Compresses K and V into a compact latent vector c_t^KV for caching", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 11.5 } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Full K, V reconstructed on-the-fly via learned projections", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 11.5 } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Decoupled RoPE-based positional key preserves position encoding", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 11.5 } },
