const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const path = require("path");

// Icon rendering
function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}
async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Color palette - Midnight/Deep Tech theme
const C = {
  bg_dark: "0F1629",
  bg_mid: "1A2342",
  bg_card: "212B4A",
  bg_light: "F4F6FB",
  accent: "00D4AA",    // teal-green
  accent2: "3B82F6",   // blue
  accent3: "F59E0B",   // amber
  white: "FFFFFF",
  text_light: "CBD5E1",
  text_muted: "8892A8",
  text_dark: "1E293B",
  card_border: "2D3A5C",
};

const FONT_H = "Trebuchet MS";
const FONT_B = "Calibri";

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.25 });

async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "DeepSeek Research";
  pres.title = "DeepSeek-V2: Efficient MoE Language Model with Multi-Head Latent Attention";

  const { FaBolt, FaMemory, FaRocket, FaBrain, FaCogs, FaChartBar, FaComments, FaLightbulb, FaCheckCircle, FaArrowDown, FaArrowUp, FaTachometerAlt } = require("react-icons/fa");

  // Helper: add a dark slide with optional top accent line
  function darkSlide() {
    const s = pres.addSlide();
    s.background = { color: C.bg_dark };
    return s;
  }

  // Helper: slide title bar
  function addSlideTitle(slide, title, subtitle) {
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });
    slide.addText(title, {
      x: 0.6, y: 0.3, w: 8.8, h: 0.55,
      fontFace: FONT_H, fontSize: 24, bold: true, color: C.white, margin: 0,
    });
    if (subtitle) {
      slide.addText(subtitle, {
        x: 0.6, y: 0.85, w: 8.8, h: 0.35,
        fontFace: FONT_B, fontSize: 12, color: C.text_muted, margin: 0,
      });
    }
  }

  // Helper: card background
  function addCard(slide, x, y, w, h) {
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w, h,
      fill: { color: C.bg_card },
      shadow: makeShadow(),
      line: { color: C.card_border, width: 0.5 },
    });
  }

  // ===================== SLIDE 1: TITLE =====================
  {
    const s = darkSlide();
    // Full-bleed dark bg with accent strip at bottom
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 4.8, w: 10, h: 0.825, fill: { color: C.accent } });
    s.addText("DeepSeek-V2", {
      x: 0.8, y: 0.9, w: 8.4, h: 1.2,
      fontFace: FONT_H, fontSize: 48, bold: true, color: C.white, margin: 0,
    });
    s.addText("A Strong, Economical, and Efficient\nMixture-of-Experts Language Model", {
      x: 0.8, y: 2.1, w: 8.4, h: 0.9,
      fontFace: FONT_B, fontSize: 20, color: C.text_light, margin: 0,
    });
    // Key stats row
    const stats = [
      { val: "236B", label: "Total Parameters" },
      { val: "21B", label: "Activated / Token" },
      { val: "128K", label: "Context Length" },
      { val: "8.1T", label: "Training Tokens" },
    ];
    stats.forEach((st, i) => {
      const sx = 0.8 + i * 2.25;
      addCard(s, sx, 3.2, 2.0, 1.35);
      s.addText(st.val, {
        x: sx, y: 3.3, w: 2.0, h: 0.6,
        fontFace: FONT_H, fontSize: 28, bold: true, color: C.accent, align: "center", margin: 0,
      });
      s.addText(st.label, {
        x: sx, y: 3.9, w: 2.0, h: 0.45,
        fontFace: FONT_B, fontSize: 11, color: C.text_muted, align: "center", margin: 0,
      });
    });
    s.addText("Multi-Head Latent Attention  ·  DeepSeekMoE", {
      x: 0.8, y: 4.85, w: 8.4, h: 0.7,
      fontFace: FONT_H, fontSize: 16, bold: true, color: C.bg_dark, align: "center", margin: 0,
    });
  }

  // ===================== SLIDE 2: MOTIVATION =====================
  {
    const s = darkSlide();
    addSlideTitle(s, "The LLM Scaling Dilemma", "Performance vs. Training Cost and Inference Speed");

    // Left column - problem framing
    addCard(s, 0.6, 1.4, 4.2, 3.8);
    const problemIcon = await iconToBase64Png(FaBolt, "#F59E0B", 256);
    s.addImage({ data: problemIcon, x: 0.9, y: 1.6, w: 0.4, h: 0.4 });
    s.addText("The Problem", {
      x: 1.4, y: 1.6, w: 3.0, h: 0.4,
      fontFace: FONT_H, fontSize: 16, bold: true, color: C.accent3, margin: 0,
    });
    s.addText([
      { text: "Scaling dense models improves quality but:", options: { breakLine: true, color: C.text_light, fontSize: 13 } },
      { text: "", options: { breakLine: true, fontSize: 8 } },
      { text: "Training costs grow super-linearly with parameter count", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 12 } },
      { text: "KV cache size scales with model dimension × layers, bottlenecking inference", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 12 } },
      { text: "Generation throughput drops as models grow larger", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 12 } },
      { text: "Existing fixes (GQA/MQA) trade performance for speed", options: { bullet: true, color: C.text_light, fontSize: 12 } },
    ], { x: 0.9, y: 2.2, w: 3.7, h: 2.8, fontFace: FONT_B, margin: 0, valign: "top" });

    // Right column - solution
    addCard(s, 5.2, 1.4, 4.2, 3.8);
    const solIcon = await iconToBase64Png(FaRocket, "#00D4AA", 256);
    s.addImage({ data: solIcon, x: 5.5, y: 1.6, w: 0.4, h: 0.4 });
    s.addText("DeepSeek-V2's Answer", {
      x: 6.0, y: 1.6, w: 3.0, h: 0.4,
      fontFace: FONT_H, fontSize: 16, bold: true, color: C.accent, margin: 0,
    });
    s.addText([
      { text: "Two architectural innovations:", options: { breakLine: true, color: C.text_light, fontSize: 13 } },
      { text: "", options: { breakLine: true, fontSize: 8 } },
      { text: "Multi-Head Latent Attention (MLA)", options: { bullet: true, breakLine: true, color: C.accent, fontSize: 12, bold: true } },
      { text: "Compresses KV cache by 93.3% while outperforming standard MHA", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 11, indentLevel: 1 } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "DeepSeekMoE", options: { bullet: true, breakLine: true, color: C.accent, fontSize: 12, bold: true } },
      { text: "Activates only 21B of 236B params, cutting training cost by 42.5%", options: { bullet: true, color: C.text_light, fontSize: 11, indentLevel: 1 } },
    ], { x: 5.5, y: 2.2, w: 3.7, h: 2.8, fontFace: FONT_B, margin: 0, valign: "top" });
  }

  // ===================== SLIDE 3: ARCHITECTURE OVERVIEW =====================
  {
    const s = darkSlide();
    addSlideTitle(s, "DeepSeek-V2 Architecture", "MLA + DeepSeekMoE in a Transformer Block");
    // Center the architecture diagram
    s.addImage({
      path: path.resolve("/app/benchmark/assets/figure_1.jpg"),
      x: 1.2, y: 1.3, w: 7.6, h: 4.0,
      sizing: { type: "contain", w: 7.6, h: 4.0 },
    });
    // Caption
    s.addText("Figure 1: Each Transformer block replaces standard MHA with MLA and dense FFN with DeepSeekMoE", {
      x: 0.6, y: 5.1, w: 8.8, h: 0.35,
      fontFace: FONT_B, fontSize: 10, italic: true, color: C.text_muted, align: "center", margin: 0,
    });
  }

  // ===================== SLIDE 4: MLA MECHANISM =====================
  {
    const s = darkSlide();
    addSlideTitle(s, "Multi-Head Latent Attention (MLA)", "Low-rank KV joint compression with decoupled RoPE");

    // Left: key points
    addCard(s, 0.6, 1.4, 4.0, 3.8);
    s.addText("How MLA Works", {
      x: 0.9, y: 1.55, w: 3.5, h: 0.35,
      fontFace: FONT_H, fontSize: 15, bold: true, color: C.accent, margin: 0,
    });
    s.addText([
      { text: "Compresses K and V into a compact latent vector c_t^KV for caching", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 11.5 } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Full K, V reconstructed on-the-fly via learned projections", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 11.5 } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Decoupled RoPE-based positional key preserves position encoding", options: { bullet: true, breakLine: true, color: C.text_light, fontSize: 11.5 } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "93.3% KV cache reduction vs. standard MHA", options: { bullet: true, breakLine: true, color: C.accent, fontSize: 12, bold: true } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Better accuracy than MHA, GQA, and MQA", options: { bullet: true, color: C.accent, fontSize: 12, bold: true } },
    ], { x: 0.9, y: 2.0, w: 3.5, h: 3.0, fontFace: FONT_B, margin: 0, valign: "top" });

    // Right: attention comparison diagram
    s.addImage({
      path: path.resolve("/app/benchmark/assets/figure_2.jpg"),
      x: 4.9, y: 1.4, w: 4.6, h: 3.8,
      sizing: { type: "contain", w: 4.6, h: 3.8 },
    });
    s.addText("MHA vs GQA vs MQA vs MLA", {
      x: 4.9, y: 5.05, w: 4.6, h: 0.3,
      fontFace: FONT_B, fontSize: 10, italic: true, color: C.text_muted, align: "center", margin: 0,
    });
  }

  // ===================== SLIDE 5: DEEPSEEK-MOE =====================
  {
    const s = darkSlide();
    addSlideTitle(s, "DeepSeekMoE: Fine-Grained Experts", "Shared expert isolation with device-limited routing");

    // Three cards in a row
    const cards = [
      { title: "Shared Experts", color: C.accent, icon: FaBrain, items: [
        "Always activated for every token",
        "Capture common knowledge across inputs",
        "Reduce redundancy in routed experts",
      ]},
      { title: "Routed Experts", color: C.accent2, icon: FaCogs, items: [
        "Sparsely activated via top-K_r gating",
        "Fine-grained segmentation increases specialization",
        "Only 21B of 236B params used per token",
      ]},
      { title: "Efficiency Design", color: C.accent3, icon: FaTachometerAlt, items: [
        "Device-limited routing: token hits ≤ M devices",
        "Reduces cross-node communication overhead",
        "Auxiliary losses enforce load balance",
      ]},
    ];

    for (let i = 0; i < 3; i++) {
      const cx = 0.6 + i * 3.1;
      addCard(s, cx, 1.4, 2.85, 3.5);
      const ic = await iconToBase64Png(cards[i].icon, cards[i].color, 256);
      s.addImage({ data: ic, x: cx + 0.2, y: 1.6, w: 0.35, h: 0.35 });
      s.addText(cards[i].title, {
        x: cx + 0.65, y: 1.6, w: 2.0, h: 0.35,
        fontFace: FONT_H, fontSize: 14, bold: true, color: cards[i].color, margin: 0,
      });
      const items = cards[i].items.map((t, j) => ({
        text: t,
        options: { bullet: true, breakLine: j < cards[i].items.length - 1, color: C.text_light, fontSize: 11 },
      }));
      s.addText(items, {
        x: cx + 0.2, y: 2.15, w: 2.45, h: 2.5,
        fontFace: FONT_B, margin: 0, valign: "top", paraSpaceAfter: 6,
      });
    }

    s.addText("Token-dropping strategy during training prevents expert overflow without affecting inference quality", {
      x: 0.6, y: 5.05, w: 8.8, h: 0.35,
      fontFace: FONT_B, fontSize: 11, italic: true, color: C.text_muted, align: "center", margin: 0,
    });
  }

  // ===================== SLIDE 6: EFFICIENCY GAINS =====================
  {
    const s = darkSlide();
    addSlideTitle(s, "Efficiency Gains vs. DeepSeek 67B", "Training cost, KV cache, and generation throughput improvements");

    // Three large metric cards
    const metrics = [
      { val: "42.5%", label: "Training Cost\nReduction", icon: FaArrowDown, color: C.accent },
      { val: "93.3%", label: "KV Cache\nReduction", icon: FaMemory, color: C.accent2 },
      { val: "5.76×", label: "Generation\nThroughput", icon: FaRocket, color: C.accent3 },
    ];

    for (let i = 0; i < 3; i++) {
      const mx = 0.6 + i * 3.15;
      addCard(s, mx, 1.4, 2.85, 2.4);
      const ic = await iconToBase64Png(metrics[i].icon, metrics[i].color, 256);
      s.addImage({ data: ic, x: mx + 1.15, y: 1.55, w: 0.55, h: 0.55 });
      s.addText(metrics[i].val, {
        x: mx, y: 2.15, w: 2.85, h: 0.7,
        fontFace: FONT_H, fontSize: 36, bold: true, color: metrics[i].color, align: "center", margin: 0,
      });
      s.addText(metrics[i].label, {
        x: mx, y: 2.85, w: 2.85, h: 0.7,
        fontFace: FONT_B, fontSize: 13, color: C.text_light, align: "center", margin: 0,
      });
    }

    // Comparison bar below
    addCard(s, 0.6, 4.1, 8.8, 1.2);
    s.addText("DeepSeek 67B (Dense)", {
      x: 0.9, y: 4.2, w: 3.8, h: 0.35,
      fontFace: FONT_H, fontSize: 13, bold: true, color: C.text_muted, margin: 0,
    });
    s.addShape(pres.shapes.RECTANGLE, { x: 0.9, y: 4.6, w: 3.8, h: 0.25, fill: { color: C.text_muted } });
    s.addText("67B activated  ·  Baseline cost  ·  1× throughput", {
      x: 0.9, y: 4.9, w: 3.8, h: 0.25,
      fontFace: FONT_B, fontSize: 10, color: C.text_muted, margin: 0,
    });

    s.addText("DeepSeek-V2 (MoE)", {
      x: 5.5, y: 4.2, w: 3.8, h: 0.35,
      fontFace: FONT_H, fontSize: 13, bold: true, color: C.accent, margin: 0,
    });
    s.addShape(pres.shapes.RECTANGLE, { x: 5.5, y: 4.6, w: 3.8, h: 0.25, fill: { color: C.accent } });
    s.addText("21B activated  ·  57.5% of cost  ·  5.76× throughput", {
      x: 5.5, y: 4.9, w: 3.8, h: 0.25,
      fontFace: FONT_B, fontSize: 10, color: C.accent, margin: 0,
    });
  }

  // ===================== SLIDE 7: MMLU SCATTER =====================
  {
    const s = darkSlide();
    addSlideTitle(s, "MMLU vs. Activated Parameters", "DeepSeek-V2 achieves Pareto-optimal efficiency among open-source models");

    // Scatter chart
    const models = [
      { name: "LLaMA 3 8B", params: 8, mmlu: 65.0 },
      { name: "Mixtral 8×7B", params: 13, mmlu: 70.6 },
      { name: "DeepSeek-V2", params: 21, mmlu: 78.5 },
      { name: "Mixtral 8×22B", params: 39, mmlu: 77.6 },
      { name: "DeepSeek 67B", params: 67, mmlu: 73.0 },
      { name: "LLaMA 2 70B", params: 70, mmlu: 69.0 },
      { name: "LLaMA 3 70B", params: 70, mmlu: 77.0 },
      { name: "Qwen1.5 72B", params: 72, mmlu: 75.6 },
    ];

    s.addChart(pres.charts.SCATTER, models.map(m => ({
      name: m.name,
      values: [{ x: m.params, y: m.mmlu }],
    })), {
      x: 0.6, y: 1.3, w: 6.0, h: 4.0,
      showTitle: false,
      chartColors: ["64748B", "64748B", "00D4AA", "64748B", "64748B", "64748B", "64748B", "64748B"],
      dataLabelPosition: "r",
      showSerName: true,
      catAxisTitle: "Activated Parameters (B)",
      valAxisTitle: "MMLU Score",
      catAxisLabelColor: "8892A8",
      valAxisLabelColor: "8892A8",
      catAxisTitleColor: "CBD5E1",
      valAxisTitleColor: "CBD5E1",
      valGridLine: { color: "2D3A5C", size: 0.5 },
      catGridLine: { color: "2D3A5C", size: 0.5 },
      chartArea: { fill: { color: C.bg_card }, roundedCorners: true },
      plotArea: { fill: { color: C.bg_card } },
      legendPos: "b",
      legendColor: "8892A8",
      legendFontSize: 9,
      lineSize: 0,
      lineDataSymbolSize: 10,
    });

    // Callout box
    addCard(s, 6.9, 1.5, 2.7, 3.5);
    s.addText("Pareto-Optimal", {
      x: 7.05, y: 1.6, w: 2.4, h: 0.35,
      fontFace: FONT_H, fontSize: 14, bold: true, color: C.accent, margin: 0,
    });
    s.addText([
      { text: "DeepSeek-V2 achieves the highest MMLU score (78.5) among all open-source models", options: { breakLine: true, color: C.text_light, fontSize: 11 } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Uses only 21B activated params — 3.3× fewer than LLaMA 3 70B", options: { breakLine: true, color: C.text_light, fontSize: 11 } },
      { text: "", options: { breakLine: true, fontSize: 6 } },
      { text: "Outperforms all 70B-class dense models on MMLU", options: { color: C.accent, fontSize: 11, bold: true } },
    ], { x: 7.05, y: 2.05, w: 2.4, h: 2.8, fontFace: FONT_B, margin: 0, valign: "top" });
  }

  // ===================== SLIDE 8: ALIGNMENT =====================
  {
    const s = darkSlide();
    addSlideTitle(s, "Alignment & Chat Evaluation", "SFT + GRPO reinforcement learning on 1.5M conversational sessions");

    // Pipeline flow
    addCard(s, 0.6, 1.4, 8.8, 1.2);
    const pipeSteps = ["Pre-training\n8.1T tokens", "SFT\n1.5M sessions", "GRPO RL\nReinforcement Learning", "DeepSeek-V2\nChat (RL)"];
    pipeSteps.forEach((step, i) => {
      const px = 0.8 + i * 2.2;
      s.addShape(pres.shapes.RECTANGLE, {
        x: px, y: 1.55, w: 1.9, h: 0.85,
        fill: { color: i === 3 ? C.accent : C.bg_mid },
        line: { color: i === 3 ? C.accent : C.card_border, width: 0.5 },
      });
      s.addText(step, {
        x: px, y: 1.55, w: 1.9, h: 0.85,
        fontFace: FONT_B, fontSize: 10, color: i === 3 ? C.bg_dark : C.text_light, align: "center", valign: "middle", margin: 0, bold: i === 3,
      });
      if (i < 3) {
        s.addText("→", {
          x: px + 1.9, y: 1.6, w: 0.3, h: 0.75,
          fontFace: FONT_B, fontSize: 18, color: C.text_muted, align: "center", valign: "middle", margin: 0,
        });
      }
    });

    // Benchmark results - 3 cards
    const benchmarks = [
      { name: "AlpacaEval 2.0", score: "38.9%", desc: "Length-controlled win rate", color: C.accent },
      { name: "MT-Bench", score: "8.97", desc: "Overall score", color: C.accent2 },
      { name: "AlignBench", score: "7.91", desc: "Overall (Chinese)", color: C.accent3 },
    ];
    benchmarks.forEach((b, i) => {
      const bx = 0.6 + i * 3.15;
      addCard(s, bx, 2.9, 2.85, 1.8);
      s.addText(b.name, {
        x: bx, y: 3.0, w: 2.85, h: 0.35,
        fontFace: FONT_H, fontSize: 13, bold: true, color: b.color, align: "center", margin: 0,
      });
      s.addText(b.score, {
        x: bx, y: 3.35, w: 2.85, h: 0.7,
        fontFace: FONT_H, fontSize: 32, bold: true, color: C.white, align: "center", margin: 0,
      });
      s.addText(b.desc, {
        x: bx, y: 4.1, w: 2.85, h: 0.35,
        fontFace: FONT_B, fontSize: 11, color: C.text_muted, align: "center", margin: 0,
      });
    });

    s.addText("DeepSeek-V2 Chat (RL) outperforms all open-source models and most closed-source models on Chinese benchmarks", {
      x: 0.6, y: 4.9, w: 8.8, h: 0.45,
      fontFace: FONT_B, fontSize: 12, italic: true, color: C.accent, align: "center", margin: 0,
    });
  }

  // ===================== SLIDE 9: TAKEAWAYS =====================
  {
    const s = darkSlide();
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });
    s.addText("Key Takeaways", {
      x: 0.6, y: 0.3, w: 8.8, h: 0.55,
      fontFace: FONT_H, fontSize: 28, bold: true, color: C.white, margin: 0,
    });
    s.addText("Architectural Innovation Unlocks Efficient Scaling", {
      x: 0.6, y: 0.85, w: 8.8, h: 0.35,
      fontFace: FONT_B, fontSize: 14, color: C.accent, margin: 0,
    });

    const takeaways = [
      { icon: FaMemory, color: C.accent, title: "MLA > MHA for Inference",
        desc: "Strictly superior to GQA/MQA — 93.3% KV cache reduction with better accuracy" },
      { icon: FaCogs, color: C.accent2, title: "Economical MoE Training",
        desc: "236B-parameter model trained at 42.5% lower cost than a 67B dense model" },
      { icon: FaChartBar, color: C.accent3, title: "Pareto-Optimal Performance",
        desc: "Only 21B activated params to match or exceed 70B-class dense models on MMLU" },
      { icon: FaRocket, color: C.accent, title: "Deployment-Ready Throughput",
        desc: "5.76× generation throughput improvement makes large-scale deployment practical" },
      { icon: FaComments, color: C.accent2, title: "Strongest Open-Source Chinese Chat",
        desc: "Competitive with closed-source systems in English; outperforms all open-source in Chinese" },
    ];

    for (let i = 0; i < takeaways.length; i++) {
      const ty = 1.4 + i * 0.82;
      addCard(s, 0.6, ty, 8.8, 0.72);
      const ic = await iconToBase64Png(takeaways[i].icon, takeaways[i].color, 256);
      s.addImage({ data: ic, x: 0.85, y: ty + 0.16, w: 0.4, h: 0.4 });
      s.addText(takeaways[i].title, {
        x: 1.45, y: ty + 0.08, w: 3.0, h: 0.3,
        fontFace: FONT_H, fontSize: 14, bold: true, color: takeaways[i].color, margin: 0,
      });
      s.addText(takeaways[i].desc, {
        x: 1.45, y: ty + 0.38, w: 7.7, h: 0.28,
        fontFace: FONT_B, fontSize: 11.5, color: C.text_light, margin: 0,
      });
    }

    // Bottom accent
    s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 5.35, w: 10, h: 0.275, fill: { color: C.accent } });
    s.addText("arxiv.org/abs/2405.04434", {
      x: 0.6, y: 5.35, w: 8.8, h: 0.275,
      fontFace: FONT_B, fontSize: 10, color: C.bg_dark, align: "center", valign: "middle", margin: 0,
    });
  }

  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Presentation saved to /app/output/final_deck.pptx");
}

main().catch(e => { console.error(e); process.exit(1); });

